<?php
namespace Tests\Feature; use App\Models\Wedding; use App\Models\WeddingGift; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class GiftReservationTest extends TestCase { use RefreshDatabase; public function test_last_gift_cannot_be_reserved_twice(): void { $wedding = Wedding::create(['name'=>'Regalos','slug'=>'regalos']); $gift = WeddingGift::create(['wedding_id'=>$wedding->id,'name'=>'Cafetera','quantity'=>1]); $this->post(route('gifts.reserve',[$wedding,$gift]),['guest_name'=>'Ana','quantity'=>1,'idempotency_key'=>'11111111-1111-4111-8111-111111111111'])->assertRedirect(); $this->post(route('gifts.reserve',[$wedding,$gift]),['guest_name'=>'Luis','quantity'=>1,'idempotency_key'=>'22222222-2222-4222-8222-222222222222'])->assertSessionHasErrors('quantity'); $this->assertSame(1,$gift->fresh()->reserved_quantity); } }
